using BrewNest.Contracts.Production;
using BrewNest.Modules.Production.Application.Interfaces;
using BrewNest.Modules.Production.Application.Services;
using BrewNest.Modules.Production.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
namespace BrewNest.UnitTests;
/// <summary>Verifies production planning, BOM, inventory, issue, variance, and cancellation rules.</summary>
public sealed class ProductionServiceTests
{
    /// <summary>Plans reject duplicate menu items and non-positive quantities.</summary>
    [Fact]public async Task PlanValidationRejectsInvalidLines(){await using var db=Database();var ports=new TestPorts();var result=await Service(db,ports).CreatePlanAsync(new("Plan",new(2026,9,24),"",[new(ports.MenuItemId,1m),new(ports.MenuItemId,0m)]),new("planner"),default);Assert.False(result.Succeeded);Assert.Contains("only once",string.Join(' ',result.Errors));}
    /// <summary>Plan release snapshots BOM and configured expected wastage.</summary>
    [Fact]public async Task PlanReleaseCalculatesBomAndWastage(){await using var db=Database();var ports=new TestPorts();var service=Service(db,ports);var plan=Value(await service.CreatePlanAsync(new("Morning",new(2026,9,24),"",[new(ports.MenuItemId,10m)]),new("planner"),default));plan=Value(await service.ReleasePlanAsync(plan.Id,new("approved",plan.Version),new("manager"),default));Assert.Equal(ProductionPlanStatus.Released,plan.Status);var order=Assert.Single(Value(await service.GetOrdersAsync(plan.Id,null,default)));var requirement=Assert.Single(order.Requirements);Assert.Equal(2m,requirement.BomQuantity);Assert.Equal(0.1m,requirement.ExpectedWastage);Assert.Equal(2.1m,requirement.RequiredQuantity);}
    /// <summary>Production order release stops when Inventory cannot reserve the requirement.</summary>
    [Fact]public async Task OrderReleaseRequiresInventoryReservation(){await using var db=Database();var ports=new TestPorts{ReserveSucceeds=false};var service=Service(db,ports);var order=await CreateOrder(service,ports);var released=await service.ReleaseOrderAsync(order.Id,new("release",order.Version),new("manager"),default);Assert.False(released.Succeeded);Assert.Contains("stock",string.Join(' ',released.Errors),StringComparison.OrdinalIgnoreCase);}
    /// <summary>Goods issue records actual consumption/wastage and calculates signed variance.</summary>
    [Fact]public async Task IssueAndCompletionCalculateVariance(){await using var db=Database();var ports=new TestPorts();var service=Service(db,ports);var order=await CreateOrder(service,ports);order=Value(await service.ReleaseOrderAsync(order.Id,new("release",order.Version),new("manager"),default));var requirement=Assert.Single(order.Requirements);order=Value(await service.IssueMaterialsAsync(order.Id,new([new(requirement.IngredientItemId,2.2m,0.2m)],"issued",order.Version),new("store"),default));Assert.Equal(ProductionOrderStatus.InProgress,order.Status);Assert.Equal(0.3m,Assert.Single(order.Requirements).Variance);order=Value(await service.CompleteOrderAsync(order.Id,new("complete",order.Version),new("chef"),default));Assert.Equal(ProductionOrderStatus.Completed,order.Status);var plan=Value(await service.GetPlanAsync(order.PlanId,default));Assert.Equal(ProductionPlanStatus.Completed,plan.Status);}
    /// <summary>Released orders release reservations on cancellation, but issued orders cannot be cancelled.</summary>
    [Fact]public async Task CancellationReleasesOnlyBeforeIssue(){await using var db=Database();var ports=new TestPorts();var service=Service(db,ports);var order=await CreateOrder(service,ports);order=Value(await service.ReleaseOrderAsync(order.Id,new("release",order.Version),new("manager"),default));var cancelled=Value(await service.CancelOrderAsync(order.Id,new("cancel",order.Version),new("manager"),default));Assert.Equal(1,ports.ReleaseCalls);Assert.Equal(ProductionOrderStatus.Cancelled,cancelled.Status);order=await CreateOrder(service,ports);order=Value(await service.ReleaseOrderAsync(order.Id,new("release",order.Version),new("manager"),default));var r=Assert.Single(order.Requirements);order=Value(await service.IssueMaterialsAsync(order.Id,new([new(r.IngredientItemId,r.BomQuantity,r.ExpectedWastage)],"issue",order.Version),new("store"),default));var late=await service.CancelOrderAsync(order.Id,new("late",order.Version),new("manager"),default);Assert.False(late.Succeeded);Assert.Contains("reversal",string.Join(' ',late.Errors),StringComparison.OrdinalIgnoreCase);}
    private static async Task<ProductionOrderResponse> CreateOrder(ProductionService service,TestPorts ports){var plan=Value(await service.CreatePlanAsync(new("Plan",new(2026,9,24),"",[new(ports.MenuItemId,10m)]),new("planner"),default));await service.ReleasePlanAsync(plan.Id,new("release",plan.Version),new("manager"),default);return Assert.Single(Value(await service.GetOrdersAsync(plan.Id,null,default)));}
    private static ProductionDbContext Database()=>new(new DbContextOptionsBuilder<ProductionDbContext>().UseInMemoryDatabase($"production-{Guid.NewGuid():N}").Options);private static ProductionService Service(ProductionDbContext db,TestPorts ports)=>new(db,ports,ports,ports,new FixedTime());private static T Value<T>(ProductionResult<T> result){Assert.True(result.Succeeded,string.Join(' ',result.Errors));return Assert.IsType<T>(result.Value);}
    private sealed class TestPorts:IProductionRecipePort,IProductionInventoryPort,IProductionDocumentNumberPort
    {
        public Guid MenuItemId{get;}=Guid.NewGuid();public Guid IngredientId{get;}=Guid.NewGuid();public bool ReserveSucceeds{get;set;}=true;public int ReleaseCalls{get;private set;}
        public Task<ProductionMenuItemReference[]> GetMenuItemsAsync(CancellationToken cancellationToken)=>Task.FromResult<ProductionMenuItemReference[]>([new(MenuItemId,"M1","Coffee")]);public Task<ProductionRecipeSnapshot?> GetRecipeAsync(Guid menuItemId,CancellationToken cancellationToken)=>Task.FromResult<ProductionRecipeSnapshot?>(new(menuItemId,1m,[new(IngredientId,0.2m,5m)]));
        public Task<ProductionCatalogItemReference[]> GetItemNamesAsync(CancellationToken cancellationToken)=>Task.FromResult<ProductionCatalogItemReference[]>([new(MenuItemId,"Coffee"),new(IngredientId,"Coffee beans")]);
        public Task<ProductionInventoryResult> ReserveAsync(string referenceId,ProductionInventoryRequirement[] requirements,string actor,CancellationToken cancellationToken)=>Task.FromResult(ReserveSucceeds?new ProductionInventoryResult(true,[],[]):new ProductionInventoryResult(false,[],["Insufficient stock."]));public Task<ProductionInventoryResult> IssueAsync(string referenceId,ProductionInventoryUsage[] usages,string actor,CancellationToken cancellationToken)=>Task.FromResult(new ProductionInventoryResult(true,[],[]));public Task<ProductionInventoryResult> ReleaseAsync(string referenceId,string reason,string actor,CancellationToken cancellationToken){ReleaseCalls++;return Task.FromResult(new ProductionInventoryResult(true,[],[]));}
        public string NextPlanNumber()=>$"PP-{Guid.NewGuid():N}"[..20];public string NextOrderNumber()=>$"PRD-{Guid.NewGuid():N}"[..20];
    }
    private sealed class FixedTime:TimeProvider{public override DateTimeOffset GetUtcNow()=>new(2026,9,24,12,0,0,TimeSpan.Zero);}
}
